import { expect, it } from "vitest";
import { asRobloxAssetId, planImport } from '@bedrock-rbx/core'

it('Example 1', () => {
  const id = asRobloxAssetId('11')
  const plan = planImport({
    config: { environments: { production: {} }, universe: { universeId: '1' } },
    environment: 'production',
    live: {
      gamePass: new Map([
        [
          id,
          {
            name: '[PROD] VIP Pass',
            description: 'Perks.',
            kind: 'gamePass',
            outputs: { iconAssetIds: { 'en-us': asRobloxAssetId('555') } },
            price: 100,
          },
        ],
      ]),
    },
    selections: [{ kind: 'gamePass', robloxId: id }],
  })
  expect(plan.items[0]?.key).toBe('vip-pass')
  expect(plan.items[0]?.icon?.path).toBe('assets/passes/vip-pass.png')
  expect(plan.edits).toStrictEqual([
    {
      key: 'vip-pass',
      collection: 'passes',
      kind: 'addEntry',
      entry: {
        name: '[PROD] VIP Pass',
        description: 'Perks.',
        icon: { 'en-us': 'assets/passes/vip-pass.png' },
        price: 100,
      },
    },
    {
      key: 'vip-pass',
      collection: 'passes',
      kind: 'declareImport',
      environment: 'production',
      importId: '11',
    },
  ])
})
